mapper.update:
UPDATE light_group
SET archive_status = 'RETURNED',
    archive_reviewer = #{operator},
    archive_review_opinion = #{reason},
    archive_version = archive_version + 1,
    updated_at = #{time}
WHERE id = #{id}
  AND archive_version = #{version}
  AND archive_status = 'PENDING_REVIEW'

UPDATE light_group
SET archive_status = 'ARCHIVED',
    archive_reviewer = #{operator},
    archive_review_opinion = #{opinion},
    archive_archived_at = #{time},
    archive_version = archive_version + 1,
    updated_at = #{time}
WHERE id = #{id}
  AND archive_version = #{version}
  AND archive_status = 'PENDING_REVIEW'

mapper.select:
SELECT * FROM light_archive_record
WHERE light_group_id = #{lightGroupId}
ORDER BY operated_at ASC, id ASC
